    // Support Center
    "support.title": "Help & Support", "support.hero_title": "How can we help?", "support.hero_desc": "Browse FAQs or contact our support team",
    "support.search_placeholder": "Search for help...", "support.no_results": "No results found",
    "support.cat_payments": "Payments", "support.cat_account": "Account", "support.cat_security": "Security", "support.cat_merchant": "Merchant",
    "support.faq_pay_1_q": "How do I add money to my wallet?", "support.faq_pay_1_a": "Go to Wallet > Add Money. You can top up via Stripe using credit/debit card. The amount is credited instantly.",
    "support.faq_pay_2_q": "Why was my payment declined?", "support.faq_pay_2_a": "Payments can be declined due to insufficient balance, daily limits, or security checks. Please check your balance and try again.",
    "support.faq_pay_3_q": "How long do transfers take?", "support.faq_pay_3_a": "Transfers between BidBlitz wallets are instant. Payouts to bank accounts may take 1-3 business days.",
    "support.faq_acc_1_q": "How do I change my password?", "support.faq_acc_1_a": "Go to More > Settings > Security & Privacy > Change Password. Enter your current password and the new one.",
    "support.faq_acc_2_q": "Can I change my email address?", "support.faq_acc_2_a": "Currently, email changes are not supported directly. Please contact our support team for assistance.",
    "support.faq_acc_3_q": "How do I delete my account?", "support.faq_acc_3_a": "Contact our support team via the form below. Account deletion is processed within 30 days.",
    "support.faq_sec_1_q": "Is my money safe?", "support.faq_sec_1_a": "Yes. All transactions are encrypted end-to-end and we use industry-standard security measures including rate limiting and fraud detection.",
    "support.faq_sec_2_q": "What happens if I suspect fraud?", "support.faq_sec_2_a": "Immediately change your password and contact our support team. We will investigate and secure your account.",
    "support.faq_sec_3_q": "How does 2FA work?", "support.faq_sec_3_a": "Two-factor authentication adds an extra layer of security. Once enabled, you'll need a verification code in addition to your password.",
    "support.faq_mer_1_q": "How do I accept payments as a merchant?", "support.faq_mer_1_a": "Use the Scanner page to scan customer barcodes. Enter the amount and the payment is processed instantly from the customer's wallet.",
    "support.faq_mer_2_q": "When do I receive my payouts?", "support.faq_mer_2_a": "You can request payouts anytime from your Merchant Dashboard. Payouts are processed within 1-3 business days.",
    "support.faq_mer_3_q": "What are the merchant fees?", "support.faq_mer_3_a": "A small platform fee is deducted per transaction. You can see the exact fee breakdown in your Merchant Dashboard.",
    "support.contact_section": "Still need help?", "support.contact_title": "Contact Support",
