    // Support Center
    "support.title": "Hilfe & Support", "support.hero_title": "Wie können wir helfen?", "support.hero_desc": "FAQ durchsuchen oder Support kontaktieren",
    "support.search_placeholder": "Hilfe suchen...", "support.no_results": "Keine Ergebnisse gefunden",
    "support.cat_payments": "Zahlungen", "support.cat_account": "Konto", "support.cat_security": "Sicherheit", "support.cat_merchant": "Händler",
    "support.faq_pay_1_q": "Wie lade ich mein Wallet auf?", "support.faq_pay_1_a": "Gehe zu Wallet > Aufladen. Du kannst per Stripe mit Kredit-/Debitkarte aufladen. Der Betrag wird sofort gutgeschrieben.",
    "support.faq_pay_2_q": "Warum wurde meine Zahlung abgelehnt?", "support.faq_pay_2_a": "Zahlungen können aufgrund von unzureichendem Guthaben, Tageslimits oder Sicherheitsprüfungen abgelehnt werden.",
    "support.faq_pay_3_q": "Wie lange dauern Überweisungen?", "support.faq_pay_3_a": "Überweisungen zwischen BidBlitz-Wallets sind sofort. Auszahlungen auf Bankkonten dauern 1-3 Werktage.",
    "support.faq_acc_1_q": "Wie ändere ich mein Passwort?", "support.faq_acc_1_a": "Gehe zu Mehr > Einstellungen > Sicherheit > Passwort ändern. Gib dein aktuelles und neues Passwort ein.",
    "support.faq_acc_2_q": "Kann ich meine E-Mail-Adresse ändern?", "support.faq_acc_2_a": "E-Mail-Änderungen sind derzeit nicht direkt möglich. Bitte kontaktiere unser Support-Team.",
    "support.faq_acc_3_q": "Wie lösche ich mein Konto?", "support.faq_acc_3_a": "Kontaktiere unser Support-Team über das untenstehende Formular. Die Kontolöschung wird innerhalb von 30 Tagen bearbeitet.",
    "support.faq_sec_1_q": "Ist mein Geld sicher?", "support.faq_sec_1_a": "Ja. Alle Transaktionen sind Ende-zu-Ende verschlüsselt und wir verwenden branchenübliche Sicherheitsmaßnahmen.",
    "support.faq_sec_2_q": "Was tue ich bei Betrugsverdacht?", "support.faq_sec_2_a": "Ändere sofort dein Passwort und kontaktiere unser Support-Team. Wir werden dein Konto untersuchen und sichern.",
    "support.faq_sec_3_q": "Wie funktioniert 2FA?", "support.faq_sec_3_a": "Zwei-Faktor-Authentifizierung fügt eine zusätzliche Sicherheitsebene hinzu. Du benötigst einen Verifizierungscode zusätzlich zum Passwort.",
    "support.faq_mer_1_q": "Wie akzeptiere ich Zahlungen als Händler?", "support.faq_mer_1_a": "Nutze die Scanner-Seite, um Kunden-Barcodes zu scannen. Gib den Betrag ein und die Zahlung wird sofort verarbeitet.",
