    // Support Center
    "support.title": "Ndihmë & Mbështetje", "support.hero_title": "Si mund t'ju ndihmojmë?", "support.hero_desc": "Shfletoni FAQ ose kontaktoni ekipin tonë",
    "support.search_placeholder": "Kërko ndihmë...", "support.no_results": "Asnjë rezultat",
    "support.cat_payments": "Pagesat", "support.cat_account": "Llogaria", "support.cat_security": "Siguria", "support.cat_merchant": "Tregtari",
    "support.faq_pay_1_q": "Si shtoj para në portofol?", "support.faq_pay_1_a": "Shko te Portofoli > Shto Para. Mund të mbushni përmes Stripe me kartë. Shuma kreditohet menjëherë.",
    "support.faq_pay_2_q": "Pse u refuzua pagesa ime?", "support.faq_pay_2_a": "Pagesat mund të refuzohen për shkak të bilancit të pamjaftueshëm, limiteve ditore ose kontrolleve të sigurisë.",
    "support.faq_pay_3_q": "Sa kohë zgjasin transfertat?", "support.faq_pay_3_a": "Transfertat mes portofolëve BidBlitz janë të menjëhershme. Tërheqjet në llogari bankare zgjasin 1-3 ditë pune.",
    "support.faq_acc_1_q": "Si ndryshoj fjalëkalimin?", "support.faq_acc_1_a": "Shko te Më shumë > Cilësimet > Siguria > Ndrysho fjalëkalimin.",
    "support.faq_acc_2_q": "A mund të ndryshoj email-in?", "support.faq_acc_2_a": "Ndryshimi i email-it nuk mbështetet aktualisht. Kontaktoni ekipin e mbështetjes.",
    "support.faq_acc_3_q": "Si fshij llogarinë time?", "support.faq_acc_3_a": "Kontaktoni ekipin tonë përmes formularit më poshtë. Fshirja përpunohet brenda 30 ditëve.",
    "support.faq_sec_1_q": "A janë paratë e mia të sigurta?", "support.faq_sec_1_a": "Po. Të gjitha transaksionet janë të enkriptuara dhe përdorim masa sigurie standarde.",
    "support.faq_sec_2_q": "Çfarë bëj nëse dyshoj mashtrim?", "support.faq_sec_2_a": "Ndryshoni menjëherë fjalëkalimin dhe kontaktoni mbështetjen. Ne do të hetojmë llogarinë tuaj.",
    "support.faq_sec_3_q": "Si funksionon 2FA?", "support.faq_sec_3_a": "Autentifikimi me dy faktorë shton një shtresë shtesë sigurie. Keni nevojë për kod verifikimi përveç fjalëkalimit.",
    "support.faq_mer_1_q": "Si pranoj pagesa si tregtar?", "support.faq_mer_1_a": "Përdorni faqen e skanerit për të skanuar barkodet e klientëve. Vendosni shumën dhe pagesa përpunohet menjëherë.",
    "support.faq_mer_2_q": "Kur i marr tërheqjet?", "support.faq_mer_2_a": "Mund të kërkoni tërheqje në çdo kohë nga Paneli i Tregtarit. Përpunimi zgjat 1-3 ditë pune.",
    "support.faq_mer_3_q": "Sa janë tarifat e tregtarit?", "support.faq_mer_3_a": "Një tarifë e vogël zbritet për transaksion. Detajet gjenden në Panelin e Tregtarit.",
