    "support.faq_pay_1_q": "Come aggiungo denaro?", "support.faq_pay_1_a": "Vai su Portafoglio > Aggiungi. Puoi ricaricare via Stripe con carta. L'importo viene accreditato istantaneamente.",
    "support.faq_pay_2_q": "Perché il mio pagamento è stato rifiutato?", "support.faq_pay_2_a": "I pagamenti possono essere rifiutati per saldo insufficiente, limiti giornalieri o controlli di sicurezza.",
    "support.faq_pay_3_q": "Quanto tempo richiedono i trasferimenti?", "support.faq_pay_3_a": "I trasferimenti tra portafogli BidBlitz sono istantanei. I prelievi bancari richiedono 1-3 giorni lavorativi.",
    "support.faq_acc_1_q": "Come cambio la password?", "support.faq_acc_1_a": "Vai su Altro > Impostazioni > Sicurezza > Cambia password.",
