    "support.faq_mer_1_q": "Come accetto pagamenti come negozio?", "support.faq_mer_1_a": "Usa la pagina Scanner per scansionare i codici a barre dei clienti. Inserisci l'importo, il pagamento viene elaborato istantaneamente.",
    "support.faq_mer_2_q": "Quando ricevo i miei pagamenti?", "support.faq_mer_2_a": "Puoi richiedere prelievi in qualsiasi momento dalla tua Dashboard. L'elaborazione richiede 1-3 giorni lavorativi.",
    "support.faq_mer_3_q": "Quali sono le commissioni?", "support.faq_mer_3_a": "Una piccola commissione viene detratta per transazione. I dettagli sono nella tua Dashboard.",
