    "support.faq_acc_3_q": "Jak usunąć konto?", "support.faq_acc_3_a": "Skontaktuj się z nami poprzez formularz poniżej. Usunięcie konta jest realizowane w ciągu 30 dni.",
    "support.faq_sec_1_q": "Czy moje pieniądze są bezpieczne?", "support.faq_sec_1_a": "Tak. Wszystkie transakcje są szyfrowane end-to-end ze standardowymi zabezpieczeniami.",
