    "support.faq_sec_3_q": "Jak działa 2FA?", "support.faq_sec_3_a": "Uwierzytelnianie dwuskładnikowe dodaje dodatkową warstwę bezpieczeństwa z kodem weryfikacyjnym.",
    "support.faq_mer_1_q": "Jak przyjmować płatności jako sklep?", "support.faq_mer_1_a": "Użyj strony Skaner do skanowania kodów klientów. Wprowadź kwotę, płatność jest przetwarzana natychmiast.",
